/**
 * Fetch/patch one issue over JSON.
 *
 * Owner D. The tenant check is explicit here rather than implied: the route
 * takes an `issueId` straight off the URL, so `assertOrgScope()` against the
 * fetched row is what stops one organization reading another's issue by id.
 *
 * Must call (do not reimplement): can, assertOrgScope
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { can } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { issueIdSchema } from "@/schemas/common";
import { updateIssueSchema } from "@/schemas/issue";
import { getIssue, updateIssue } from "@/server/services/issue-service";

export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ issueId: string }> };

export async function GET(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { issueId } = await context.params;
    const parsedId = issueIdSchema.safeParse(issueId);
    if (!parsedId.success) {
      return failure("validation_failed", "Malformed issue id.");
    }

    const actor = await getActor(orgSlug);
    const found = await getIssue(actor, actor.orgId, parsedId.data);
    assertOrgScope(actor, found.issue.orgId);

    const allowed = can(actor, "issue:read", {
      kind: "issue",
      orgId: found.issue.orgId,
      projectId: found.issue.projectId,
      issueId: found.issue.id,
      authorId: found.issue.authorId,
      assigneeId: found.issue.assigneeId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot read this issue.");
    }

    return Response.json(found);
  } catch (error) {
    return errorResponse(error);
  }
}

export async function PATCH(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { issueId } = await context.params;
    const actor = await getActor(orgSlug);

    const body: unknown = await request.json();
    const parsed = updateIssueSchema.safeParse({
      ...(typeof body === "object" && body !== null ? body : {}),
      orgId: actor.orgId,
      issueId,
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad issue patch.");
    }

    const current = await getIssue(actor, actor.orgId, parsed.data.issueId);
    assertOrgScope(actor, current.issue.orgId);

    const allowed = can(actor, "issue:update", {
      kind: "issue",
      orgId: current.issue.orgId,
      projectId: current.issue.projectId,
      issueId: current.issue.id,
      authorId: current.issue.authorId,
      assigneeId: current.issue.assigneeId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot update this issue.");
    }

    const updated = await updateIssue(actor, parsed.data);
    return Response.json(updated);
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Sends a signed test payload to one endpoint.
 *
 * Owner D. The point of the route is to prove the *signature* round-trips, so
 * it returns the signature it computed alongside the payload — a customer can
 * verify their own check against a known-good pair without waiting for a real
 * event.
 *
 * Must call (do not reimplement): can, signPayload
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { can } from "@/lib/permissions";
import { webhookIdSchema } from "@/schemas/common";
import { listWebhooks, signPayload } from "@/server/services/webhook-service";

export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ endpointId: string }> };

export async function POST(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { endpointId } = await context.params;
    const parsedId = webhookIdSchema.safeParse(endpointId);
    if (!parsedId.success) {
      return failure("validation_failed", "Malformed endpoint id.");
    }

    const actor = await getActor(orgSlug);

    const allowed = can(actor, "webhook:manage", {
      kind: "webhook",
      orgId: actor.orgId,
      webhookId: parsedId.data,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot manage webhooks here.");
    }

    // Listing is org-scoped, so an endpoint id from another tenant simply is
    // not in the result and the route reports it as missing.
    const endpoints = await listWebhooks(actor, actor.orgId);
    const endpoint = endpoints.find((row) => row.id === parsedId.data);
    if (endpoint === undefined) {
      return failure("not_found", "No such endpoint in this organization.");
    }

    const payload = JSON.stringify({
      eventType: "webhook.test",
      orgId: actor.orgId,
      endpointId: endpoint.id,
      sentAt: new Date().toISOString(),
    });

    return Response.json({
      delivered: endpoint.enabled,
      url: endpoint.url,
      signature: signPayload(endpoint.secret, payload),
      payload,
    });
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Receives third-party callbacks validated with `inboundWebhookSchema`.
 *
 * Owner D. The receiver is deliberately dumb: it validates the envelope, charges
 * a rate limit and hands the payload to the event bus. Anything that needs to
 * happen as a result is a subscriber's job, so a slow handler cannot make the
 * sender time out and retry.
 *
 * Must call (do not reimplement): inboundWebhookSchema, consumeRateLimit
 */

import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { errorResponse, failure } from "@/app/api/_lib/responses";
import { emit } from "@/lib/event-bus";
import { consumeRateLimit } from "@/lib/rate-limit";
import { inboundWebhookSchema } from "@/schemas/webhook";
import { toIsoTimestamp } from "@/types/common";

export const dynamic = "force-dynamic";

const INBOUND_BUCKET = "webhook:inbound";

export async function POST(request: Request): Promise<Response> {
  try {
    // The sender is not a tenant, so the bucket is the shared anonymous one.
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, INBOUND_BUCKET);
    if (!verdict.allowed) {
      return failure("rate_limited", "Too many inbound callbacks.");
    }

    const body: unknown = await request.json();
    const parsed = inboundWebhookSchema.safeParse(body);
    if (!parsed.success) {
      return failure("validation_failed", "Unrecognised callback envelope.");
    }

    await emit("webhook.delivery_requested", {
      orgId: ANONYMOUS_ORG_ID,
      actorId: null,
      occurredAt: toIsoTimestamp(parsed.data.occurredAt),
      eventType: `inbound.${parsed.data.source}`,
      payload: parsed.data.payload,
    });

    // 202: the callback is accepted, not yet acted on.
    return Response.json({ accepted: true, eventId: parsed.data.eventId }, { status: 202 });
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Shared JSON helpers for the route handlers.
 *
 * Owner D. Every handler under `src/app/api` returns the same envelope as the
 * Server Actions — `{ error: AppErrorShape }` on failure — so a client can use
 * one parser for both. The status code comes from `HTTP_STATUS_BY_CODE`, which
 * is the single mapping from domain error code to HTTP.
 */

import { HTTP_STATUS_BY_CODE, toAppError } from "@/lib/errors";
import type { AppErrorShape, ApiErrorBody } from "@/types/api";

/** Turns any thrown value into the JSON error envelope with the right status. */
export function errorResponse(error: unknown): Response {
  const shape: AppErrorShape = toAppError(error);
  const body: ApiErrorBody = { error: shape };
  return Response.json(body, { status: HTTP_STATUS_BY_CODE[shape.code] });

