      });

      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({
        commentId: comment.id,
        issueId: issue.id,
        mentionedUserIds: [tenant.userIds.owner],
      });
    } finally {
      off();
    }
  });

  it("allows the author to edit inside the edit window", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "original body",
      parentId: null,
      mentionedUserIds: [],
    });

    vi.setSystemTime(new Date("2026-01-01T00:05:00.000Z"));

    const edited = await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "edited within the window",
    });

    expect(edited.body).toBe("edited within the window");
  });

  it("refuses an edit once the edit window has closed", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-01-02T00:00:00.000Z"));

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "original body",
      parentId: null,
      mentionedUserIds: [],
    });

    vi.setSystemTime(new Date("2026-01-02T00:16:00.000Z"));

    await expect(
      commentService.updateComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "too late",
      }),
    ).rejects.toThrow(/edit window/);
  });

  it("lets an admin delete a comment they did not write", async () => {
    const comment = await commentService.createComment(tenant.actors.member, {
  await orgRepo.updateOrg(tenant.org.id, {
    orgId: tenant.org.id,
    settings: { digestHourUtc },
  });
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

/** Subscribes a member to the digest by setting one `digestOnly` preference. */
async function subscribeToDigest(tenant: Tenant): Promise<void> {
  await preferenceRepo.upsertPreference({
    orgId: tenant.org.id,
    userId: tenant.userIds.member,
    kind: "comment_created",
    inApp: false,
    email: false,
    digestOnly: true,
  });
}

async function insertNotificationAt(
  tenant: Tenant,
  at: Date,
  title: string,
): Promise<void> {
  vi.useFakeTimers();
  vi.setSystemTime(at);
  try {
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      kind: "comment_created",
      title,
      body: title,
      href: "/issues/1",
      actorId: null,
      channels: ["email"],
    });
  } finally {
    vi.useRealTimers();
  }
}

/** Pulls a `<td>key</td><td>value</td>` cell out of the generic email table. */
function cell(html: string, key: string): string | null {
  const match = html.match(new RegExp(`<td>${key}</td><td>([^<]*)</td>`));
  return match?.[1] ?? null;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.restoreAllMocks();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

