import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/**
 * Billing lock.
 *
 * A workspace whose subscription is not in good standing is read-only: reads
 * and billing keep working (billing is the way out), every member write is
 * refused. The rule lives here, pure, so the service guard, the billing
 * summary and the shell banner cannot disagree about who is locked.
 */

export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is read-only until billing is resolved (${reason})`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * Why the workspace is locked at `now`, or `null` when it is writable. No
 * subscription row at all counts as writable — there is nothing to be behind
 * on.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return hasReached(subscription.currentPeriodEnd, now)
        ? "trial_ended"
        : null;
    case "canceled":
      // A cancellation with no date took effect already.
      return subscription.cancelAt === null ||
        hasReached(subscription.cancelAt, now)
        ? "canceled"
        : null;
  }
}

function hasReached(at: string, now: Date): boolean {
  return now.getTime() >= new Date(at).getTime();
}

