/** The pure workspace-lock rule. */
import { describe, expect, it } from "vitest";
import { lockReasonFor } from "@/lib/billing-lock";
import type { Subscription, SubscriptionStatus } from "@/types/billing";
import type { IsoTimestamp, SubscriptionId } from "@/types/common";
import { ORG_A } from "../helpers/factories";

const NOW = new Date("2026-06-15T12:00:00.000Z");
const PAST = "2026-06-01T00:00:00.000Z" as IsoTimestamp;
const FUTURE = "2026-07-01T00:00:00.000Z" as IsoTimestamp;

function subscription(
  status: SubscriptionStatus,
  overrides: Partial<Subscription> = {},
): Subscription {
  return {
    id: "01HZZZSUBSUBSUBSUBSUBSUBSU" as SubscriptionId,
    orgId: ORG_A,
    plan: "growth",
    interval: "monthly",
    status,
    seats: 1,
    currentPeriodStart: PAST,
    currentPeriodEnd: FUTURE,
    cancelAt: null,
    createdAt: PAST,
    updatedAt: PAST,
    ...overrides,
  };
}

describe("lib/billing-lock", () => {
  it("leaves a workspace without a subscription, or an active one, writable", () => {
    expect(lockReasonFor(null, NOW)).toBeNull();
    expect(lockReasonFor(subscription("active"), NOW)).toBeNull();
  });

  it("locks a past-due workspace", () => {
    expect(lockReasonFor(subscription("past_due"), NOW)).toBe("past_due");
  });

  it("locks a trial from the moment its period ends", () => {
    expect(lockReasonFor(subscription("trialing"), NOW)).toBeNull();
    expect(
      lockReasonFor(
        subscription("trialing", {
          currentPeriodEnd: NOW.toISOString() as IsoTimestamp,
        }),
        NOW,
      ),
    ).toBe("trial_ended");
    expect(
      lockReasonFor(subscription("trialing", { currentPeriodEnd: PAST }), NOW),
    ).toBe("trial_ended");
  });

  it("locks a cancellation once its date is reached, or at once without one", () => {
    expect(
      lockReasonFor(subscription("canceled", { cancelAt: FUTURE }), NOW),
    ).toBeNull();
    expect(
      lockReasonFor(
        subscription("canceled", { cancelAt: NOW.toISOString() as IsoTimestamp }),
        NOW,
      ),
    ).toBe("canceled");
    expect(lockReasonFor(subscription("canceled"), NOW)).toBe("canceled");
  });
});
EOF
